#!/usr/bin/env node
// .mcp.json owns shared servers; ignored .mcp.local.json may add local servers.
// This script generates everything that repeats it:
//   1. .codex/config.toml (Codex), entirely generated.
//   2. The `dependencies:` block of each .agents/skills/*/agents/openai.yaml
//      (Codex skill metadata). Only the lines between the markers
//        # BEGIN generated by npm run agents:sync
//        # END generated
//      are rewritten; everything outside them stays hand-written. Inside the
//      block, the `# servers: a, b` line is the list of .mcp.json keys the
//      skill depends on, and each item's `description:` is hand-written and
//      kept as-is. transport, command and url always come from .mcp.json.
//      To add or drop a server, edit the `# servers:` line and run sync.
//      A file with a `dependencies:` block but no markers is converted once,
//      taking the server list and descriptions from its `value:` entries.
//
//   node scripts/agents/sync-mcp.mjs          write all generated output
//   node scripts/agents/sync-mcp.mjs --check  exit 1 if any of it is stale
//
// No dependencies (no YAML library): this script owns the block format.
// Paths are resolved from this file, so it runs from any cwd.
import {
  chmodSync,
  existsSync,
  lstatSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  writeFileSync,
} from "node:fs";
import { spawnSync } from "node:child_process";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { homedir } from "node:os";
import { isDeepStrictEqual } from "node:util";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const SOURCE = join(ROOT, ".mcp.json");
const LOCAL_SOURCE = join(ROOT, ".mcp.local.json");
const TARGET = join(ROOT, ".codex", "config.toml");
const SKILLS = join(ROOT, ".agents", "skills");

// Codex-only settings that .mcp.json cannot express. Codex starts MCP servers
// with a small default environment (HOME, PATH, USER, ...), so variables a
// server needs must be forwarded explicitly with env_vars.
const STDIO_DEFAULTS = { startup_timeout_sec: 60 }; // first `npx` run downloads
const CODEX_EXTRAS = {
  "chrome-devtools": {
    env_vars: ["DISPLAY", "WAYLAND_DISPLAY", "XDG_RUNTIME_DIR"],
  },
  vercel: { default_tools_approval_mode: "prompt" },
  maestro: {
    tool_timeout_sec: 300,
    env_vars: [
      "ADB_SERVER_SOCKET",
      "ANDROID_HOME",
      "ANDROID_SDK_ROOT",
      "JAVA_HOME",
      "MAESTRO_BIN",
      "DISPLAY",
      "WAYLAND_DISPLAY",
      "XDG_RUNTIME_DIR",
      "WSL_DISTRO_NAME",
      "WSL_INTEROP",
      "WSLENV",
    ],
  },
};

const HEADER = [
  "# GENERATED LOCAL FILE — shared .mcp.json + optional .mcp.local.json",
  "# Run npm run agents:sync; never commit this file or OAuth credentials.",
  "# Do not edit by hand; `npm run agents:check` fails when this file is stale.",
  "# Codex loads this file only when the project is trusted.",
  "",
].join("\n");

const VAR = /\$\{([A-Za-z_][A-Za-z0-9_]*)(:-[^}]*)?\}/g;
const BARE_KEY = /^[A-Za-z0-9_-]+$/;

const fail = (msg) => {
  console.error(`sync-mcp: ${msg}`);
  process.exit(2);
};

const tomlString = (s) => JSON.stringify(String(s));
const tomlKey = (k) => (BARE_KEY.test(k) ? k : tomlString(k));
const tomlValue = (v) => {
  if (Array.isArray(v)) return `[${v.map(tomlValue).join(", ")}]`;
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  if (typeof v === "string") return tomlString(v);
  fail("unsupported configuration value type");
};
const hasVar = (s) => typeof s === "string" && /\$\{/.test(s);
const varNames = (s) => [...s.matchAll(VAR)].map((m) => m[1]);

// Single-quote for POSIX shells, keeping ${VAR} / ${VAR:-default} expandable.
function shellWord(s) {
  const quote = (t) => (t ? `'${t.replaceAll("'", `'\\''`)}'` : "");
  let out = "";
  let last = 0;
  for (const m of s.matchAll(VAR)) {
    out += quote(s.slice(last, m.index)) + `"${m[0]}"`;
    last = m.index + m[0].length;
  }
  out += quote(s.slice(last));
  return out || "''";
}

// Codex does not expand ${VAR} in command/args. Wrap such servers in bash,
// which expands the same ${VAR} and ${VAR:-default} forms for any client.
function wrapForShell(command, args) {
  const words = [command, ...args].map(shellWord).join(" ");
  const script = `exec ${words} "$@"`;
  return { command: "bash", args: ["-c", script, "mcp-server"] };
}

function convertStdio(name, s) {
  if (!s.command) fail(`${name}: stdio server needs "command"`);
  const args = s.args ?? [];
  const out = { command: s.command, args };
  const forwarded = new Set();
  if ([s.command, ...args].some(hasVar)) {
    Object.assign(out, wrapForShell(s.command, args));
    for (const a of [s.command, ...args].filter(hasVar))
      for (const v of varNames(a)) forwarded.add(v);
  }
  const env = {};
  for (const [k, v] of Object.entries(s.env ?? {})) {
    const whole = /^\$\{([A-Za-z_][A-Za-z0-9_]*)\}$/.exec(v);
    if (whole && whole[1] === k) forwarded.add(k);
    else if (hasVar(v))
      fail(`${name}: env ${k} uses a variable form Codex cannot express`);
    else env[k] = v;
  }
  if (Object.keys(env).length) out.env = env;
  if (s.cwd) out.cwd = s.cwd;
  if (forwarded.size) out.env_vars = [...forwarded].sort();
  return { ...out, ...STDIO_DEFAULTS };
}

function convertHttp(name, s) {
  if (!s.url) fail(`${name}: http server needs "url"`);
  if (hasVar(s.url))
    fail(`${name}: Codex cannot expand variables in "url"; use a literal`);
  const out = { url: s.url };
  const literal = {};
  const fromEnv = {};
  for (const [k, v] of Object.entries(s.headers ?? {})) {
    const bearer = /^Bearer \$\{([A-Za-z_][A-Za-z0-9_]*)\}$/.exec(v);
    const whole = /^\$\{([A-Za-z_][A-Za-z0-9_]*)\}$/.exec(v);
    if (k.toLowerCase() === "authorization" && bearer)
      out.bearer_token_env_var = bearer[1];
    else if (whole) fromEnv[k] = whole[1];
    else if (hasVar(v))
      fail(`${name}: header ${k} uses a variable form Codex cannot express`);
    else literal[k] = v;
  }
  if (Object.keys(literal).length) out.http_headers = literal;
  if (Object.keys(fromEnv).length) out.env_http_headers = fromEnv;
  return out;
}

export function generate(json, localNames = []) {
  const servers = json?.mcpServers;
  if (!servers || typeof servers !== "object") fail(`no "mcpServers" object`);
  let toml = HEADER;
  for (const [name, s] of Object.entries(servers)) {
    if (!BARE_KEY.test(name))
      fail(`server name "${name}" must be [A-Za-z0-9_-]`);
    const type = s.type ?? (s.url ? "http" : "stdio");
    let conf;
    if (type === "stdio") conf = convertStdio(name, s);
    else if (type === "http" || type === "streamable-http")
      conf = convertHttp(name, s);
    else
      fail(`${name}: Codex supports stdio and streamable HTTP, not "${type}"`);
    Object.assign(conf, CODEX_EXTRAS[name]);
    if (localNames.includes(name)) conf.default_tools_approval_mode = "prompt";
    const tables = [];
    toml += `\n[mcp_servers.${name}]\n`;
    for (const [k, v] of Object.entries(conf)) {
      if (v && typeof v === "object" && !Array.isArray(v)) tables.push([k, v]);
      else toml += `${k} = ${tomlValue(v)}\n`;
    }
    for (const [k, table] of tables) {
      toml += `\n[mcp_servers.${name}.${k}]\n`;
      for (const [tk, tv] of Object.entries(table))
        toml += `${tomlKey(tk)} = ${tomlValue(tv)}\n`;
    }
  }
  return toml;
}

// Local additions cannot silently replace the shared server definitions.
export function mergeServerSources(shared, local) {
  for (const [label, source] of [
    ["shared", shared],
    ["local", local],
  ]) {
    const servers = source?.mcpServers;
    if (!servers || typeof servers !== "object" || Array.isArray(servers))
      throw new Error(`${label} configuration needs a mcpServers object`);
    for (const [name, server] of Object.entries(servers)) {
      if (
        !BARE_KEY.test(name) ||
        !server ||
        typeof server !== "object" ||
        Array.isArray(server)
      )
        throw new Error(`${label} configuration contains an invalid server`);
    }
  }
  if (
    Object.keys(local.mcpServers).some((name) =>
      Object.hasOwn(shared.mcpServers, name),
    )
  )
    throw new Error("local server names must not replace shared server names");
  return { mcpServers: { ...shared.mcpServers, ...local.mcpServers } };
}

// Use the client's own project-local writer; never edit its credential store.
export function syncClaudeLocal(servers, current, run) {
  for (const [name, definition] of Object.entries(servers)) {
    const previous = current[name];
    if (isDeepStrictEqual(previous, definition)) continue;
    const remove = () => run(["mcp", "remove", name, "--scope", "local"]);
    const add = (value) =>
      run(["mcp", "add-json", "--scope", "local", name, JSON.stringify(value)]);
    if (previous && remove().status !== 0)
      throw new Error("Cannot replace Claude project-local registration");
    if (add(definition).status !== 0) {
      const restored = !previous || add(previous).status === 0;
      throw new Error(
        restored
          ? "Claude local sync failed; previous settings preserved"
          : "Claude local sync failed; restore previous registration before continuing",
      );
    }
  }
}

// ---- Skill metadata: agents/openai.yaml `dependencies:` blocks ----

export const BLOCK_BEGIN = "# BEGIN generated by npm run agents:sync";
export const BLOCK_END = "# END generated";
const SERVERS_LINE = /^# servers:(.*)$/m;

const yamlString = (s) => JSON.stringify(String(s)); // JSON strings are YAML

// Reads `value:`/`description:` pairs from a dependencies block this script
// (or the original hand-written files) produced.
function parseTools(block) {
  const tools = [];
  for (const line of block.split("\n")) {
    const value = /^\s+value:\s*(".*")\s*$/.exec(line);
    if (value) tools.push({ name: JSON.parse(value[1]) });
    const desc = /^\s+description:\s*(".*")\s*$/.exec(line);
    if (desc && tools.length) tools.at(-1).description = JSON.parse(desc[1]);
  }
  return tools;
}

function toolEntry(name, description, servers) {
  const s = servers[name];
  if (!s) fail(`skill dependency "${name}" is not a server in .mcp.json`);
  const type = s.type ?? (s.url ? "http" : "stdio");
  const lines = [
    `    - type: "mcp"`,
    `      value: ${yamlString(name)}`,
    `      description: ${yamlString(description ?? `${name} MCP server (see AGENTS.md)`)}`,
  ];
  if (type === "stdio") {
    const words = [s.command, ...(s.args ?? [])];
    if (words.some(hasVar))
      fail(`${name}: skill metadata cannot express \${VAR} in command/args`);
    lines.push(`      transport: "stdio"`);
    lines.push(`      command: ${yamlString(words.join(" "))}`);
  } else {
    lines.push(`      transport: "streamable_http"`);
    lines.push(`      url: ${yamlString(s.url)}`);
  }
  return lines;
}

// Returns the file text with its generated block rewritten, or null when the
// file declares no dependencies. Exported for tests.
export function renderSkillDependencies(text, servers) {
  let before, block, after;
  const begin = text.indexOf(BLOCK_BEGIN);
  if (begin !== -1) {
    const end = text.indexOf(BLOCK_END, begin);
    if (end === -1) fail(`"${BLOCK_BEGIN}" without "${BLOCK_END}"`);
    before = text.slice(0, begin);
    block = text.slice(begin, end);
    after = text.slice(end + BLOCK_END.length).replace(/^\r?\n/, "");
  } else {
    // One-time conversion of a hand-written top-level dependencies block.
    const start = text.search(/^dependencies:/m);
    if (start === -1) return null;
    const rest = text.slice(start).split("\n");
    let n = 1;
    while (n < rest.length && (rest[n] === "" || /^[\s#]/.test(rest[n]))) n++;
    while (n > 1 && rest[n - 1] === "") n--;
    before = text.slice(0, start);
    block = rest.slice(0, n).join("\n");
    after = rest.slice(n).join("\n").replace(/^\n+/, "");
  }
  const tools = parseTools(block);
  const listed = SERVERS_LINE.exec(block)?.[1];
  const names = listed
    ? listed
        .split(",")
        .map((n) => n.trim())
        .filter(Boolean)
    : tools.map((t) => t.name);
  const descriptions = new Map(tools.map((t) => [t.name, t.description]));
  const out = [BLOCK_BEGIN, `# servers: ${names.join(", ")}`, "dependencies:"];
  out.push(names.length ? "  tools:" : "  tools: []");
  for (const name of names)
    out.push(...toolEntry(name, descriptions.get(name), servers));
  out.push(BLOCK_END);
  return before + out.join("\n") + "\n" + after;
}

function skillMetadataFiles() {
  if (!existsSync(SKILLS)) return [];
  return readdirSync(SKILLS, { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .map((d) => join(SKILLS, d.name, "agents", "openai.yaml"))
    .filter((file) => existsSync(file))
    .sort();
}

// Every generated file as [absolute path, wanted text].
function outputs(json, merged) {
  const localNames = Object.keys(merged.mcpServers).filter(
    (name) => !Object.hasOwn(json.mcpServers, name),
  );
  const result = [[TARGET, generate(merged, localNames)]];
  for (const file of skillMetadataFiles()) {
    const want = renderSkillDependencies(
      readFileSync(file, "utf8"),
      json.mcpServers,
    );
    if (want !== null) result.push([file, want]);
  }
  return result;
}

function main() {
  const check = process.argv.includes("--check");
  let json;
  try {
    json = JSON.parse(readFileSync(SOURCE, "utf8"));
  } catch {
    fail(`cannot read valid JSON from ${relative(ROOT, SOURCE)}`);
  }
  // Refuse to write private configuration into a tracked or unignored path.
  for (const file of [LOCAL_SOURCE, TARGET]) {
    const rel = relative(ROOT, file);
    if (existsSync(file) && lstatSync(file).isSymbolicLink())
      fail(`${rel} must be a regular local file, not a symlink`);
    const tracked = spawnSync(
      "git",
      ["ls-files", "--error-unmatch", "--", rel],
      { cwd: ROOT, stdio: "ignore" },
    );
    const ignored = spawnSync("git", ["check-ignore", "--quiet", "--", rel], {
      cwd: ROOT,
      stdio: "ignore",
    });
    if (tracked.status !== 1 || ignored.status !== 0)
      fail(`${rel} must be untracked and Git-ignored before generation`);
  }
  let merged, local;
  try {
    local = existsSync(LOCAL_SOURCE)
      ? JSON.parse(readFileSync(LOCAL_SOURCE, "utf8"))
      : { mcpServers: {} };
    merged = mergeServerSources(json, local);
  } catch {
    fail(
      "invalid MCP source: require mcpServers objects and unique local server names; local names cannot override shared servers",
    );
  }
  if (!check && existsSync(LOCAL_SOURCE)) chmodSync(LOCAL_SOURCE, 0o600);
  let stale = 0;
  for (const [file, want] of outputs(json, merged)) {
    const rel = relative(ROOT, file);
    const have = existsSync(file) ? readFileSync(file, "utf8") : "";
    if (have === want) {
      if (!check && file === TARGET) chmodSync(file, 0o600);
      if (check) console.log(`${rel} is up to date.`);
      continue;
    }
    if (check) {
      console.error(`${rel} is out of date. Run: npm run agents:sync`);
      stale++;
      continue;
    }
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, want, file === TARGET ? { mode: 0o600 } : undefined);
    if (file === TARGET) chmodSync(file, 0o600);
    console.log(`Wrote ${rel}`);
  }
  if (stale) process.exit(1);
  if (process.argv.includes("--claude-local")) {
    if (check) fail("use --claude-local with sync, not --check");
    // A custom Claude config location must be handled explicitly, not guessed.
    if (process.env.CLAUDE_CONFIG_DIR)
      fail(
        "--claude-local currently requires Claude's default config location",
      );
    try {
      const configFile = join(homedir(), ".claude.json");
      const config = existsSync(configFile)
        ? JSON.parse(readFileSync(configFile, "utf8"))
        : {};
      const current = config.projects?.[ROOT]?.mcpServers ?? {};
      syncClaudeLocal(local.mcpServers, current, (args) =>
        spawnSync("claude", args, { cwd: ROOT, stdio: "pipe" }),
      );
      console.log("Claude project-local additions are in sync.");
    } catch {
      fail(
        "Claude local sync failed; check the CLI installation and project-local registration (no credentials were printed)",
      );
    }
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1])
  main();
